func (r *Database) ValidateCreate() (warnings admission.Warnings, err error) {
    if r.Spec.Replicas > 10 {
        return nil, field.Invalid(
            field.NewPath("spec").Child("replicas"),
            r.Spec.Replicas,
            "cannot exceed 10 replicas",
        )
    }
    return nil, nil
}

