func (r *Database) Default() {
    if r.Spec.Version == "" {
        r.Spec.Version = "14.0"  // Default PostgreSQL version
    }
}

func (r *DatabaseReconciler) SetupWithManager(mgr ctrl.Manager) error {
    return ctrl.NewControllerManagedBy(mgr).
        For(&examplev1.Database{}).
        // Use predicates to filter events
        WithEventFilter(predicate.GenerationChangedPredicate{}).
        // Configure rate limiting
        WithOptions(controller.Options{
            MaxConcurrentReconciles: 5,
            RateLimiter: workqueue.NewItemExponentialFailureRateLimiter(
                100*time.Millisecond,
                5*time.Minute,
            ),
        }).
        Complete(r)
}

// Namespace-scoped controller
func (r *DatabaseReconciler) SetupWithManager(mgr ctrl.Manager) error {
    return ctrl.NewControllerManagedBy(mgr).
        For(&examplev1.Database{}).
        // Watch only specific namespaces
        WithEventFilter(predicate.Funcs{
            CreateFunc: func(e event.CreateEvent) bool {
                return r.isAllowedNamespace(e.Object.GetNamespace())
            },
        }).
        Complete(r)
}

func (r *DatabaseReconciler) isAllowedNamespace(ns string) bool {
    // Check if namespace belongs to allowed tenant
    return strings.HasPrefix(ns, "tenant-")
}
